 function documentValidation(d){const permission=d.document_type==='quote'?'sales.quotes.finalize':'sales.invoices.finalize';if(!can(permission))return'Votre rôle ne permet pas de finaliser ce document.';const saleLines=(d.lines||[]).filter(line=>['item','free_item','option','variant'].includes(line.line_type)&&!line.optional),progress=isProgressDocument(d),billedLines=progress?saleLines.filter(line=>Number(line.quantity)>0):saleLines;if(!d.client_id)return'Sélectionnez un client.';if(!billedLines.length)return progress?'Augmentez l’avancement d’au moins une ligne.':'Ajoutez au moins une ligne.';if(billedLines.some(line=>!String(line.name||'').trim()||Number(line.quantity)<=0))return'Complétez la désignation et la quantité de chaque ligne.';const totals=calc().document(d.lines,d.discount_rate);if(totals.ttc<=0)return'Le montant total doit être supérieur à zéro pour finaliser.';return'';}
