 function syncFinalizationDates(issueDate){const form=document.getElementById('document-finalize-form');if(!form||!issueDate)return;for(const name of['situation_date','due_date']){const input=form.elements.namedItem(name);if(!input)continue;input.min=issueDate;if(!input.value||input.value<issueDate)input.value=issueDate;}}
 function invoiceFinalizationDates(d){const today=localToday(),latest=latestFinalInvoiceDate(d),form=document.getElementById('document-finalize-form');if(form&&!form.reportValidity())return null;const values=form?Object.fromEntries(new FormData(form)): {},issue=String(values.issue_date||d.issue_date||today),situation=String(values.situation_date||d.supply_date||issue),due=String(values.due_date||d.due_date||issue);if(latest&&issue<latest){global.PilozCommercialV2.notify(`La date de la facture ne peut pas être antérieure au ${displayDate(latest)}, date de la dernière facture définitive.`,'error');return null;}if(isProgressDocument(d)&&situation<issue){global.PilozCommercialV2.notify('La date de la situation ne peut pas être antérieure à la date de la facture.','error');return null;}if(due<issue){global.PilozCommercialV2.notify('La date d’échéance ne peut pas être antérieure à la date de la facture.','error');return null;}return{issue_date:issue,supply_date:isProgressDocument(d)?situation:(d.supply_date||issue),due_date:due};}
 async function saveQuote(confirmed=false){const d=s().draft;if(ui.finalizing||quoteLocked(d)||!can('sales.quotes.finalize'))return;const error=documentValidation(d);if(error){global.PilozCommercialV2.notify(error,'error');return;}const wasDraft=d.status==='draft';if(wasDraft&&!confirmed){askQuoteValidation();return;}closeFinalizeModal();ui.finalizing=true;try{const savedId=await app().saveDocument(wasDraft?{silent:true,skipRefresh:true}:true);if(!savedId)throw new Error('Le devis n’a pas pu être enregistré.');if(wasDraft){await api().rpc('transition_document_status',{target_document_id:savedId,target_status:'pending'});await app().refresh();}global.PilozCommercialV2.notify(wasDraft?'Devis validé.':'Devis enregistré.','success');if(global.PilozDocumentViewerV2){global.PilozDocumentViewerV2.open(savedId);Promise.resolve(global.PilozDocumentViewerV2.primeDocumentPreview(savedId)).catch(error2=>console.warn('[PILOZ PDF] Aperçu du devis différé',error2?.message||error2));}else location.hash=`#document-viewer?id=${encodeURIComponent(savedId)}&type=quote`;}catch(error2){global.PilozCommercialV2.notify(error2.message||'La validation du devis a échoué. Le brouillon est conservé.','error');}finally{ui.finalizing=false;}}
 async function finalizeDocument(confirmed=false){const d=s().draft;if(ui.finalizing||locked(d))return;const error=documentValidation(d);if(error){global.PilozCommercialV2.notify(error,'error');return;}if(!confirmed){askInvoiceFinalization();return;}const dates=invoiceFinalizationDates(d);if(!dates)return;Object.assign(d,dates);closeFinalizeModal();ui.finalizing=true;try{const savedId=await app().saveDocument({silent:true,skipRefresh:true});if(!savedId)throw new Error('Le brouillon n’a pas pu être enregistré. La finalisation est annulée.');const saved=s().draft;if(!saved?.id)throw new Error('Enregistrez d’abord le brouillon.');const result=await app().finalizeCurrentDocument({throwOnError:true});if(!result)throw new Error('La finalisation a échoué. Le brouillon est conservé.');openFinalizedConsultation(result.id||saved.id);}catch(error2){const message=String(error2?.message||'');global.PilozCommercialV2.notify(message.includes('invoice_issue_date_before_last_finalized')?'La date de la facture doit être postérieure ou égale à celle de la dernière facture définitive.':message||'La finalisation a échoué. Le brouillon est conservé.','error');}finally{ui.finalizing=false;}}
