 function syncItemCreator(source){const form=document.getElementById('document-v2-item-form');if(!form)return;const cost=Number(form.elements.cost_price.value)||0,marginValue=Number(form.elements.margin_rate.value)||0,sale=Number(form.elements.sale_price.value)||0;if(source==='margin'||source==='cost')form.elements.sale_price.value=(cost*(1+marginValue/100)).toFixed(2);else form.elements.margin_rate.value=cost?((sale-cost)/cost*100).toFixed(2):'0.00';}
